#include "load_pass.h"

#include "core_shaders.h" // generated by CMake: shaders/*.{vert,frag}, baked by qsb
#include "targets.h"

#include <rhi/qrhi.h>
#include <rhi/qshader.h>

#include <QtCore/QJsonDocument>
#include <QtCore/QStringList>
#include <QtGui/QColor>

namespace srpss_core {

namespace {

// std140, the load pass's block (shaders/load.frag).
struct LoadBlock
{
    float params[4]; // x: the fragment loop's length
};
static_assert(sizeof(LoadBlock) == 16, "std140 Load block");

constexpr float kFullTriangle[6] = { -1.0f, -1.0f, 3.0f, -1.0f, -1.0f, 3.0f };
constexpr int kTargetObjects = 3; // texture, render target, pass descriptor
constexpr int kPassObjects = 4;   // two buffers, bindings, pipeline

QShader shaderFrom(const unsigned char *data, unsigned int size)
{
    return QShader::fromSerialized(QByteArray(reinterpret_cast<const char *>(data), int(size)));
}

} // namespace

bool LoadConfig::fromJson(const QByteArray &json, LoadConfig *out, QString *error)
{
    LoadConfig c;
    const QJsonObject o = QJsonDocument::fromJson(json).object();
    const QStringList known = { QStringLiteral("width"), QStringLiteral("height"), QStringLiteral("draws"),
                                QStringLiteral("iterations"), QStringLiteral("timing") };
    for (auto it = o.begin(); it != o.end(); ++it) {
        if (!known.contains(it.key())) {
            *error = QStringLiteral("unknown load option '%1' (%2)").arg(it.key(), known.join(QStringLiteral(", ")));
            return false;
        }
    }
    c.width = o.value(QStringLiteral("width")).toInt(c.width);
    c.height = o.value(QStringLiteral("height")).toInt(c.height);
    c.draws = o.value(QStringLiteral("draws")).toInt(c.draws);
    c.iterations = o.value(QStringLiteral("iterations")).toInt(c.iterations);
    c.timing = o.value(QStringLiteral("timing")).toString(c.timing);
    if (c.width < 8 || c.height < 8 || c.width > 4096 || c.height > 4096) {
        *error = QStringLiteral("the load target is 8 to 4096 pixels a side");
        return false;
    }
    if (c.draws < 1 || c.draws > 1024) {
        *error = QStringLiteral("the load pass draws 1 to 1024 times");
        return false;
    }
    if (c.iterations < 1 || c.iterations > 4096) {
        *error = QStringLiteral("the load pass's loop is 1 to 4096 steps");
        return false;
    }
    if (c.timing != QLatin1String("pass") && c.timing != QLatin1String("before")) {
        *error = QStringLiteral("unknown timing '%1' (pass, before)").arg(c.timing);
        return false;
    }
    *out = c;
    return true;
}

QJsonObject LoadConfig::toJson() const
{
    QJsonObject o;
    o.insert(QStringLiteral("width"), width);
    o.insert(QStringLiteral("height"), height);
    o.insert(QStringLiteral("draws"), draws);
    o.insert(QStringLiteral("iterations"), iterations);
    o.insert(QStringLiteral("timing"), timing);
    return o;
}

struct LoadPass::Resources
{
    QRhi *rhi = nullptr;
    ColorTarget target;
    std::unique_ptr<QRhiBuffer> vertices;
    std::unique_ptr<QRhiBuffer> uniforms;
    std::unique_ptr<QRhiShaderResourceBindings> srb;
    std::unique_ptr<QRhiGraphicsPipeline> pipeline;
    bool staticUploaded = false;
    float uploadedIterations = -1.0f;
};

LoadPass::LoadPass(const LoadConfig &config) : m_config(config) {}

LoadPass::~LoadPass() = default; // release() ran on the render thread (the frame driver's contract)

void LoadPass::retune(const LoadConfig &config)
{
    m_config.draws = config.draws;
    m_config.iterations = config.iterations;
    m_config.timing = config.timing;
}

bool LoadPass::ensure(QRhi *rhi, QString *error)
{
    if (m_res && m_res->rhi == rhi)
        return true;
    if (m_res) {
        *error = QStringLiteral("the load pass was created on another QRhi");
        return false;
    }
    auto res = std::make_unique<Resources>();
    res->rhi = rhi;
    if (!createColorTarget(rhi, QSize(m_config.width, m_config.height), QByteArrayLiteral("srpss core load target"),
                           &res->target, error))
        return false;
    const QShader vs = shaderFrom(load_vert_qsb, load_vert_qsb_size);
    const QShader fs = shaderFrom(load_frag_qsb, load_frag_qsb_size);
    if (!vs.isValid() || !fs.isValid()) {
        *error = QStringLiteral("the load pass's baked shaders are not valid");
        return false;
    }
    res->vertices.reset(rhi->newBuffer(QRhiBuffer::Immutable, QRhiBuffer::VertexBuffer, sizeof(kFullTriangle)));
    res->uniforms.reset(rhi->newBuffer(QRhiBuffer::Dynamic, QRhiBuffer::UniformBuffer, sizeof(LoadBlock)));
    res->vertices->setName(QByteArrayLiteral("srpss core load vertices"));
    res->uniforms->setName(QByteArrayLiteral("srpss core load block"));
    if (!res->vertices->create() || !res->uniforms->create()) {
        *error = QStringLiteral("the load pass's buffers could not be created");
        return false;
    }
    res->srb.reset(rhi->newShaderResourceBindings());
    res->srb->setName(QByteArrayLiteral("srpss core load bindings"));
    res->srb->setBindings({ QRhiShaderResourceBinding::uniformBuffer(0, QRhiShaderResourceBinding::FragmentStage,
                                                                     res->uniforms.get()) });
    if (!res->srb->create()) {
        *error = QStringLiteral("the load pass's bindings could not be created");
        return false;
    }
    res->pipeline.reset(rhi->newGraphicsPipeline());
    res->pipeline->setName(QByteArrayLiteral("srpss core load"));
    // Additive: every draw's fragments are executed and change the target (no draw is redundant).
    QRhiGraphicsPipeline::TargetBlend blend;
    blend.enable = true;
    blend.srcColor = QRhiGraphicsPipeline::One;
    blend.dstColor = QRhiGraphicsPipeline::One;
    blend.srcAlpha = QRhiGraphicsPipeline::One;
    blend.dstAlpha = QRhiGraphicsPipeline::One;
    res->pipeline->setTargetBlends({ blend });
    res->pipeline->setShaderStages({ { QRhiShaderStage::Vertex, vs }, { QRhiShaderStage::Fragment, fs } });
    QRhiVertexInputLayout layout;
    layout.setBindings({ { quint32(2 * sizeof(float)) } });
    layout.setAttributes({ { 0, 0, QRhiVertexInputAttribute::Float2, 0 } });
    res->pipeline->setVertexInputLayout(layout);
    res->pipeline->setCullMode(QRhiGraphicsPipeline::None);
    res->pipeline->setShaderResourceBindings(res->srb.get());
    res->pipeline->setRenderPassDescriptor(res->target.renderPass.get());
    if (!res->pipeline->create()) {
        *error = QStringLiteral("the load pass's pipeline could not be created");
        return false;
    }
    m_res = std::move(res);
    m_live.storeRelaxed(kTargetObjects + kPassObjects);
    return true;
}

bool LoadPass::record(QRhi *rhi, QRhiCommandBuffer *cb, QString *error)
{
    if (!rhi || !cb) {
        *error = QStringLiteral("no QRhi or command buffer in this frame");
        return false;
    }
    if (!ensure(rhi, error))
        return false;
    Resources &r = *m_res;
    primeForLoad(rhi, cb, r.target.texture.get()); // rule C: at creation (nothing else reads this target)
    QRhiResourceUpdateBatch *updates = nullptr;
    if (!r.staticUploaded || r.uploadedIterations != float(m_config.iterations)) {
        updates = rhi->nextResourceUpdateBatch();
        if (!r.staticUploaded) {
            updates->uploadStaticBuffer(r.vertices.get(), kFullTriangle);
            r.staticUploaded = true;
        }
        LoadBlock block = {};
        block.params[0] = float(m_config.iterations);
        updates->updateDynamicBuffer(r.uniforms.get(), 0, sizeof(LoadBlock), &block);
        r.uploadedIterations = float(m_config.iterations);
    }
    // The target keeps its contents (rule B); the additive draws accumulate over what it holds.
    cb->beginPass(r.target.renderTarget.get(), QColor(0, 0, 0, 0), { 1.0f, 0 }, updates);
    const QSize size = r.target.texture->pixelSize();
    cb->setGraphicsPipeline(r.pipeline.get());
    cb->setViewport(QRhiViewport(0, 0, float(size.width()), float(size.height())));
    cb->setShaderResources();
    const QRhiCommandBuffer::VertexInput input(r.vertices.get(), 0);
    cb->setVertexInput(0, 1, &input);
    for (int i = 0; i < m_config.draws; ++i)
        cb->draw(3);
    cb->endPass();
    m_passes.fetchAndAddRelaxed(1);
    return true;
}

void LoadPass::release()
{
    if (!m_res)
        return;
    m_res->pipeline.reset();
    m_res->srb.reset();
    m_res->uniforms.reset();
    m_res->vertices.reset();
    m_res->target.reset();
    m_res.reset();
    m_live.storeRelaxed(0);
}

} // namespace srpss_core
